const TITLES: Record<string, string> = {
  '/home': 'Home',
  '/services': 'Services',
  '/drrm': 'Emergency & DRRM Info',
  '/home/emergency-info': 'Emergency & DRRM Info',
  '/maps': 'Maps',
  '/health': 'Health',
  '/reports': 'Reports',
  '/announcements': 'Announcements',
  '/settings': 'Settings',
