        accessibilityElementsHidden={searching}
        importantForAccessibility={searching ? 'no-hide-descendants' : 'auto'}>
        <Image source={require('@/assets/logo/barangayan-logo-1024.png')}
          style={styles.logo} contentFit="contain" accessibilityLabel="Barangayan" />
        <ThemedText type="residentHeader" accessibilityRole="header"
          numberOfLines={pathname === '/announcements' || searchAvoidance ? 1 : undefined}
          adjustsFontSizeToFit={pathname === '/announcements' || searchAvoidance}
          minimumFontScale={0.6}
          style={[styles.title, title && title.length > 14 ? styles.longTitle : undefined, { color: theme.resident.onAccent }]}>{title}</ThemedText>
        <View onLayout={event => { const next = event.nativeEvent.layout.x; setSearchX(current => current === next ? current : next); }}>
          <Pressable accessibilityRole="button" accessibilityLabel="Search"
            accessibilityState={emergencyMapActive ? { expanded: false } : undefined}
            onPress={() => { setMapSearch(emergencyMapActive); openSearch(pathname); }} style={styles.button}>
            <Ionicons name="search" size={22} color={theme.resident.onAccent} />
          </Pressable>
        </View>
        <HeaderAction label={announcementsUnreadCount > 0 ? `View announcements, ${announcementsUnreadCount} unread` : 'View announcements'}
          selected={pathname === '/announcements'} reducedMotion={reducedMotion}
          onPress={() => router.navigate('/announcements')}>
            <NotificationBell size={22} color={pathname === '/announcements' ? theme.resident.accentText : theme.resident.onAccent} presentation="resident" />
        </HeaderAction>
        <HeaderAction label="Open settings" selected={pathname === '/settings'} reducedMotion={reducedMotion}
          onPress={() => router.navigate('/settings')}>
            <Ionicons name="menu" size={24} color={pathname === '/settings' ? theme.resident.accentText : theme.resident.onAccent} />
        </HeaderAction>
      </Animated.View>
      <View style={styles.searchLayer} pointerEvents={searching ? 'box-none' : 'none'}
        accessibilityElementsHidden={!searching}
        importantForAccessibility={searching ? 'auto' : 'no-hide-descendants'}>
        {searching ? (
          <Pressable accessibilityRole="button" accessibilityLabel="Back from search"
            onPress={closeSearch} style={styles.button}>
            <Ionicons name="arrow-back" size={24} color={theme.resident.onAccent} />
          </Pressable>
        ) : null}
        <Animated.View style={[styles.field, fieldStyle]} onTouchStart={resetSearchIdle}>
          <View pointerEvents="none" style={[styles.fieldSurface, { backgroundColor: theme.resident.card }]} />
          {mapSearch ? <Pressable accessibilityRole="button" accessibilityLabel="Collapse header search" accessibilityState={{ expanded: true }} onPress={closeSearch} style={styles.button}>
            <Ionicons name="search" size={18} color={theme.resident.muted} />
          </Pressable> : <Ionicons name="search" size={18} color={theme.resident.muted} />}
          {searching ? <TextInput
            ref={input} value={query} onChangeText={value => { setQuery(value); resetSearchIdle(); }} maxLength={120} editable={searching}
            // Explore's field is the way back to editing: focusing it reopens the entry with the submitted query.
            onFocus={() => {
              if (!searchActive.current) { input.current?.blur(); Keyboard.dismiss(); return; }
              if (entering.current) resetSearchIdle(); else editSearch();
            }} onSelectionChange={resetSearchIdle} onKeyPress={resetSearchIdle}
            accessibilityLabel="Search services, announcements and your records"
            placeholder="Search Barangayan" placeholderTextColor={theme.resident.muted}
            returnKeyType="search" autoCorrect={false}
            onSubmitEditing={() => submitSearch(query)} style={[styles.input, { color: theme.resident.text, fontFamily: getMobileFontFamily(fontId) }]} /> : null}
          {query ? (
            <Pressable accessibilityRole="button" accessibilityLabel="Clear search"
              onPress={() => { if (!enteringSearch) { editSearch(''); return; } setQuery(''); input.current?.focus(); }} style={styles.clear}>
              <Ionicons name="close-circle" size={18} color={theme.resident.muted} />
            </Pressable>
          ) : null}
          {enteringSearch ? (
            <Pressable accessibilityRole="button" accessibilityLabel="Submit search" accessibilityState={{ disabled: !searchable }}
              disabled={!searchable} onPress={() => submitSearch(query)} style={styles.submit}>
              <ThemedText type="smallBold" style={{ color: searchable ? theme.resident.accentText : theme.resident.muted }}>Search</ThemedText>
            </Pressable>
          ) : null}
        </Animated.View>
      </View>
    </View>
  </View>;
}

/** Animate only presentation; the full touch target and unread badge stay stable. */
function HeaderAction({ label, selected, reducedMotion, onPress, children }: {
  label: string;
  selected: boolean;
  reducedMotion: boolean;
  onPress: () => void;
  children: ReactNode;
}) {
  const { resident } = useTheme();
  const selection = useSharedValue(Number(selected));
  const press = useSharedValue(0);
  useEffect(() => {
    selection.value = reducedMotion ? Number(selected) : withTiming(Number(selected), {
      duration: selected ? 260 : 180,
      easing: Easing.bezier(0.16, 1, 0.3, 1),
    });
    return () => cancelAnimation(selection);
  }, [selected, reducedMotion, selection]);
  useEffect(() => {
    if (reducedMotion) { cancelAnimation(press); press.value = 0; }
    return () => cancelAnimation(press);
  }, [reducedMotion, press]);
  const surfaceStyle = useAnimatedStyle(() => ({
    opacity: selection.value,
    transform: [{ scale: reducedMotion ? 1 : 0.84 + selection.value * 0.16 }],
  }));
  const pressStyle = useAnimatedStyle(() => ({ opacity: press.value * 0.14 }));
  const contentStyle = useAnimatedStyle(() => ({
    transform: [{ scale: reducedMotion ? 1 : 1 - press.value * 0.08 }],
  }));
  const setPressed = (value: number) => {
    press.value = reducedMotion ? value : withTiming(value, {
      duration: value ? 90 : 180,
      easing: Easing.out(Easing.cubic),
    });
  };
  return <Pressable accessibilityRole="button" accessibilityLabel={label}
    accessibilityState={{ selected }} onPress={onPress}
    onPressIn={() => setPressed(1)} onPressOut={() => setPressed(0)} style={styles.button}>
    <Animated.View pointerEvents="none" style={[styles.actionContent, contentStyle]}>
      {/* Route state owns visibility so a stale native animation cannot leave a pale surface behind the white inactive icon. */}
      {selected ? <Animated.View style={[styles.iconHighlight, { backgroundColor: resident.accentSoft, borderColor: resident.onAccent }, surfaceStyle]} /> : null}
      <Animated.View style={[styles.pressHighlight, { backgroundColor: selected ? resident.accentText : resident.onAccent }, pressStyle]} />
      {children}
    </Animated.View>
  </Pressable>;
}
const styles = StyleSheet.create({
  row: { minHeight: 56, paddingVertical: 6, marginLeft: 16, marginRight: 8, justifyContent: 'center' },
  normal: { minHeight: 44, flexDirection: 'row', alignItems: 'center' },
  logo: { width: 36, height: 36, borderRadius: 18, marginRight: 12, flexShrink: 0 },
  title: { fontSize: 22, lineHeight: 28, flex: 1, minWidth: 0 },
  longTitle: { fontSize: 19, lineHeight: 22 },
  button: { width: 44, height: 44, flexShrink: 0, alignItems: 'center', justifyContent: 'center' },
  actionContent: { width: 40, height: 40, alignItems: 'center', justifyContent: 'center' },
  iconHighlight: { position: 'absolute', inset: 0, borderRadius: 24, borderWidth: 1 },
  pressHighlight: { position: 'absolute', inset: 0, borderRadius: 24 },
  searchLayer: { position: 'absolute', left: -12, right: 4, top: 6, height: 44 },
  field: { position: 'absolute', top: 0, height: 44, borderRadius: 24, paddingLeft: 14, flexDirection: 'row', alignItems: 'center', overflow: 'hidden' },
  fieldSurface: { position: 'absolute', left: 0, right: 0, top: 2, bottom: 2, borderRadius: 24 },
  input: { flex: 1, minWidth: 0, paddingHorizontal: 8, fontSize: 15, height: 44 },
  clear: { width: 44, height: 44, justifyContent: 'center', alignItems: 'center' },
  submit: { minWidth: 44, height: 44, paddingHorizontal: 10, justifyContent: 'center', alignItems: 'center' },
});type RGB = readonly [number, number, number];

function rgb(hex: string): RGB {
  return [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
}

function mix(color: string, surface: string, amount: number): string {
  const source = rgb(color);
  return `#${rgb(surface).map((channel, index) => Math.round(source[index] + (channel - source[index]) * amount).toString(16).padStart(2, '0')).join('')}`;
}

function luminance(hex: string): number {
  const [red, green, blue] = rgb(hex).map((channel) => {
    const value = channel / 255;
    return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
  });
  return red * 0.2126 + green * 0.7152 + blue * 0.0722;
}

function contrast(a: string, b: string): number {
  const first = luminance(a);
  const second = luminance(b);
  return (Math.max(first, second) + 0.05) / (Math.min(first, second) + 0.05);
}

function foreground(background: string): string {
  return contrast('#000000', background) > contrast('#ffffff', background) ? '#000000' : '#ffffff';
}

function readable(color: string, surface: string, text: string): string {
  if (contrast(color, surface) >= 4.5) return color;
  let low = 0;
  let high = 1;
  for (let step = 0; step < 16; step += 1) {
    const middle = (low + high) / 2;
    if (contrast(mix(color, text, middle), surface) >= 4.5) high = middle;
    else low = middle;
  }
  return mix(color, text, high);
}

/** Opt-in resident roles. Saved preferences and the legacy palette stay unchanged. */
export function getResidentTheme(mode: 'light' | 'dark', selectedAccent: string) {
  const dark = mode === 'dark';
  const card = dark ? '#17191C' : '#FFFFFF';
  const surface = dark ? '#24272B' : '#F4F4F4';
  const text = dark ? '#F5F5F5' : '#222222';
  const muted = dark ? '#BDC0C5' : '#6A6A6A';
  const accent = /^#[\da-f]{6}$/i.test(selectedAccent) ? selectedAccent : '#0F6E5B';
  const accentSoft = mix(accent, card, dark ? 0.82 : 0.90);
  const accentPressed = mix(accent, '#000000', 0.22);
  const tone = (color: string) => {
    const soft = mix(color, card, 0.90);
    return { ink: readable(readable(readable(color, card, text), surface, text), soft, text), soft };
  };
  const danger = tone('#D93A3A');
  const dangerFill = '#8F1D1D';
  const success = tone('#0F6E5B');
  const warning = tone('#B86E00');
  const info = tone('#2563EB');
  const rose = tone('#C2416B');
  const callFill = '#E8930C';
  return {
    card, surface, text, muted, accent, accentSoft, accentPressed,
    // Optical media surfaces preserve the original evidence image in either theme.
    mediaBackdrop: '#000000', mediaForeground: '#FFFFFF', mediaScrim: 'rgba(0,0,0,0.55)',
    onAccent: foreground(accent),
    accentNeedsOutline: contrast(accent, card) < 3,
    onAccentPressed: foreground(accentPressed),
    accentText: readable(readable(readable(accent, card, text), surface, text), accentSoft, text),
    border: dark ? '#34373C' : '#EBEBEB',
    controlBorder: dark ? '#868C95' : '#767676',
    pressed: dark ? '#30343A' : '#EBEBEB',
    scrim: 'rgba(0,0,0,0.40)',
    danger: danger.ink, dangerSoft: danger.soft, onDanger: foreground(danger.ink),
    dangerFill, dangerFillPressed: '#D93A3A', onDangerFill: foreground(dangerFill),
    dangerFillNeedsOutline: contrast(dangerFill, card) < 3,
    success: success.ink, successSoft: success.soft,
    warning: warning.ink, warningSoft: warning.soft,
    info: info.ink, infoSoft: info.soft,
    onWarning: foreground(warning.ink), onInfo: foreground(info.ink),
    callFill, onCallFill: foreground(callFill), callNeedsOutline: contrast(callFill, card) < 3,
    rose: rose.ink, onRose: foreground(rose.ink),
  };
}

export const ResidentLayout = {
  screenPadding: 20,
  panelRadius: 16,
  controlRadius: 12,
  overlayRadius: 24,
  rowPadding: 16,
  controlHeight: 48,
} as const;import type { Tables } from '@barangayan/shared';
import { addEventListener } from '@react-native-community/netinfo';
import { useFocusEffect } from 'expo-router';
import { useCallback, useMemo, useState, useSyncExternalStore } from 'react';
import { AppState } from 'react-native';
import { activeAdvisories, advisoryExpiry } from '@/lib/home-announcement';
import { RefreshResource } from '@/lib/refresh-resource';
import { supabase } from '@/lib/supabase';

type Announcement = Tables<'announcements'>;
async function loadAnnouncements(signal: AbortSignal, alerts: boolean) {
  const now = new Date().toISOString();
  const items: Announcement[] = [];
  // Only currently published active alerts, never full announcement history.
  for (let page = 0; page < 100; page++) {
    if (signal.aborted) throw new Error('Cancelled');
    let query = supabase.from('announcements').select('*', alerts ? { count: 'exact' } : undefined).is('deleted_at', null)
      .lte('published_at', now).order('published_at', { ascending: false }).order('id', { ascending: false });
    if (alerts) query = query.eq('category', 'emergency').gt('alert_expires_at', now).range(items.length, items.length + 99);
    else query = query.limit(1);
    const { data, error, count } = await query.abortSignal(signal).retry(false);
    if (error || !data) throw error ?? new Error('Invalid announcement response');
    items.push(...data);
    if (!alerts || (count !== null && count !== undefined && items.length >= count)) return { items, refreshedAt: new Date().toISOString() };
    if (!data.length || count === null || count === undefined) throw new Error('Incomplete advisory response');
  }
  throw new Error('Advisory response exceeded the safe page limit');
}
const loadNews = (signal: AbortSignal) => loadAnnouncements(signal, false);
const loadAlerts = (signal: AbortSignal) => loadAnnouncements(signal, true);

export function useHomeAnnouncements(scope: string) {
  const newsResource = useMemo(() => new RefreshResource(scope, loadNews, 'Announcements could not be loaded. Please try again.', undefined, 12_000), [scope]);
  const alertResource = useMemo(() => new RefreshResource(scope, loadAlerts, 'Advisories could not be checked. Please try again.', undefined, 12_000), [scope]);
  const news = useSyncExternalStore(newsResource.subscribe, newsResource.getSnapshot, newsResource.getSnapshot);
  const alerts = useSyncExternalStore(alertResource.subscribe, alertResource.getSnapshot, alertResource.getSnapshot);
  const [offline, setOffline] = useState(false);
  const [clock, setClock] = useState(Date.now);
  const refresh = useCallback(() => Promise.all([newsResource.refresh(), alertResource.refresh()]), [newsResource, alertResource]);
  useFocusEffect(useCallback(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    let active = AppState.currentState !== 'background' && AppState.currentState !== 'inactive';
    const tick = () => {
      clearTimeout(timer);
      if (!active) return;
      const now = Date.now();
      setClock(now);
      const next = Math.min(...[...(alertResource.getSnapshot().data?.items ?? []), ...(newsResource.getSnapshot().data?.items ?? [])].map(advisoryExpiry).filter((value): value is number => value !== null && value > now));
      if (Number.isFinite(next)) timer = setTimeout(tick, Math.min(next - now, 2_147_483_647));
    };
    let network: (() => void) | undefined;
    const start = () => {
      network ??= addEventListener(state => setOffline(state.isConnected === false || state.isInternetReachable === false));
      newsResource.activate(); alertResource.activate(); tick(); void refresh();
    };
    const stop = () => { clearTimeout(timer); network?.(); network = undefined; newsResource.cancel(); alertResource.cancel(); };
    const unsubscribe = alertResource.subscribe(tick);
    const unsubscribeNews = newsResource.subscribe(tick);
    if (active) start();
    const listener = AppState.addEventListener('change', state => { active = state === 'active'; if (active) start(); else stop(); });
    return () => { active = false; stop(); unsubscribe(); unsubscribeNews(); listener.remove(); };
  }, [newsResource, alertResource, refresh]));
  return { news, alerts, clock, active: activeAdvisories(alerts.data?.items ?? [], clock), offline,
    refresh, retryNews: newsResource.refresh, retryAlerts: alertResource.refresh };
}interface RefreshSnapshot<T> {
  data: T | undefined;
  fetching: boolean;
  error: string | null;
}

/** One read owner per account/filter. Ordinary reads join; invalidations queue
 * one follow-up and prevent a pre-invalidation reply from being published. */
export class RefreshResource<T> {
  private snapshot: RefreshSnapshot<T> = { data: undefined, fetching: false, error: null };
  private listeners = new Set<() => void>();
  private pending: Promise<void> | null = null;
  private controller: AbortController | null = null;
  private revision = 0;
  private active = true;

  constructor(
    readonly key: string,
    private load: (signal: AbortSignal) => Promise<T>,
    private message: string,
    private reconcile: (previous: T | undefined, next: T) => T = (_, next) => next,
    private timeoutMs = 30_000,
  ) {}

  getSnapshot = () => this.snapshot;
  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
  };
  private publish(snapshot: RefreshSnapshot<T>) {
    this.snapshot = snapshot;
    this.listeners.forEach(listener => listener());
  }
  activate = () => { this.active = true; };
  cancel = () => {
    this.active = false;
    this.revision++;
    this.controller?.abort();
    this.controller = null;
    this.pending = null;
    this.snapshot = { ...this.snapshot, fetching: false };
  };
  refresh = (): Promise<void> => {
    if (!this.active) return Promise.resolve();
    if (this.pending) return this.pending;
    this.publish({ ...this.snapshot, fetching: true, error: null });
    // Install ownership before invoking transport, including synchronous callers.
    const work = Promise.resolve().then(async () => {
      while (this.active && this.pending === work) {
        const revision = this.revision;
        const controller = new AbortController();
        this.controller = controller;
        let timeout: ReturnType<typeof setTimeout> | undefined;
        let removeAbortListener: (() => void) | undefined;
        try {
          const data = await Promise.race([this.load(controller.signal), new Promise<never>((_, reject) => {
            const abort = () => reject(new Error(this.message));
            controller.signal.addEventListener('abort', abort, { once: true });
            removeAbortListener = () => controller.signal.removeEventListener('abort', abort);
            timeout = setTimeout(() => controller.abort(), this.timeoutMs);
          })]);
          if (!this.active || this.pending !== work) return;
          if (revision === this.revision) {
            if (controller.signal.aborted) throw new Error(this.message);
            this.publish({ data: this.reconcile(this.snapshot.data, data), fetching: false, error: null });
            return;
          }
        } catch {
          if (!this.active || this.pending !== work) return;
          if (revision === this.revision) {
            this.publish({ ...this.snapshot, fetching: false, error: this.message });
            return;
          }
        } finally {
          clearTimeout(timeout);
          removeAbortListener?.();
          if (this.controller === controller) this.controller = null;
        }
      }
    }).finally(() => { if (this.pending === work) this.pending = null; });
    this.pending = work;
    return work;
  };
  invalidate = (): Promise<void> => {
    this.revision++;
    this.controller?.abort();
    return this.refresh();
  };
}@AGENTS.md
